MDJ([
{"n":"Inhibiteurs de la pompe à protons (IPP) et anti-H2","i":"ipp","s":"gastro","nn":["Inhibiteurs de la pompe à protons (IPP)","IPP","Antihistaminiques H2 gastriques","Antihistaminiques H2","Oméprazole","Ésoméprazole","Pantoprazole"],"d":["Les **IPP** sont les antisécrétoires gastriques les plus puissants : ils traitent le **reflux gastro-œsophagien**, l'**ulcère** et protègent l'estomac sous AINS. Très prescrits, ils sont souvent poursuivis **sans indication** au long cours, avec des effets indésirables réels."],"ma":["Ils bloquent de façon irréversible la **pompe à protons** (H+/K+ ATPase) des cellules pariétales de l'estomac, étape finale de la sécrétion d'acide : la production d'acide diminue de plus de 90 %. Les **anti-H2** (famotidine) bloquent la stimulation par l'histamine, de façon moins puissante."],"sch":{"k":"ipp","cap":"Les IPP bloquent la pompe à protons ; les anti-H2 bloquent la stimulation par l'histamine."},"m":[{"dci":"Oméprazole","br":"Mopral®","pr":"comprimés, gélules, IV"},{"dci":"Ésoméprazole","br":"Inexium®","pr":"oral, IV (hémorragie digestive)"},{"dci":"Pantoprazole","br":"Inipomp®, Eupantol®","pr":"moins d'interactions (clopidogrel)"},{"dci":"Lansoprazole, rabéprazole","br":"Lanzor®, Pariet®","pr":"oral"},{"dci":"Famotidine","br":"Pepdine®","pr":"anti-H2"}],"ind":["**Reflux gastro-œsophagien**, œsophagite","**Ulcère gastroduodénal**, éradication d'**Helicobacter pylori** (avec 2 ou 3 antibiotiques)","**Prévention des lésions sous AINS** chez le patient à risque (âge > 65 ans, antécédent d'ulcère, association à un antiagrégant ou un corticoïde)","**Hémorragie digestive haute** (IPP IV), syndrome de Zollinger-Ellison"],"ci":["Hypersensibilité","Association à certains antirétroviraux (rilpivirine, atazanavir)"],"ef":["Céphalées, diarrhée, douleurs abdominales, nausées"],"eg":["Au long cours : **hypomagnésémie**, **carence en vitamine B12**, fractures (ostéoporose)","**Infections digestives** (C. difficile) et pneumopathies favorisées","Néphrite interstitielle (rare)"],"it":["**Clopidogrel** : oméprazole et ésoméprazole diminuent son efficacité (préférer le pantoprazole)","Médicaments dont l'absorption dépend de l'acidité (kétoconazole, certains ITK anticancéreux, fer)","Méthotrexate à forte dose : toxicité augmentée"],"v":["Voie orale, **le matin à jeun, 15 à 30 minutes avant le petit-déjeuner** (efficacité maximale)","Comprimés gastrorésistants : **ne pas croquer ni écraser** (certaines gélules peuvent être ouvertes et mélangées à une compote ou administrées par sonde selon le produit)","IV : bolus puis perfusion continue dans l'hémorragie digestive","**Réévaluer régulièrement l'indication** ; arrêt progressif après un traitement prolongé (rebond d'acidité)"],"sc":["Efficacité (brûlures, régurgitations, douleurs épigastriques)","Diarrhée, signes d'hémorragie digestive (méléna, hématémèse)"],"sb":["Magnésémie et vitamine B12 en cas de traitement prolongé"],"p":["Personne âgée : souvent prescrits au long cours sans indication : réévaluer (fractures, C. difficile, carences)","Enfant : formes adaptées (granulés, gélules ouvrables)","Grossesse : oméprazole utilisable","Insuffisance hépatique : réduire les doses"],"edu":["Prendre le matin à jeun ; ne pas croquer les comprimés","Règles hygiéno-diététiques du reflux : surélever la tête du lit, éviter les repas copieux et tardifs, l'alcool, le tabac, perdre du poids","Ne pas prolonger seul le traitement ; en parler au médecin"],"cat":["Méléna, vomissement de sang : urgence (constantes, voie veineuse, prévenir)","Diarrhée importante sous IPP et antibiotiques : prévenir (C. difficile)"],"r":["Bloquent la pompe à protons : **moins de 90 % d'acide**","**À jeun, 15 à 30 minutes avant le petit-déjeuner**, sans croquer","Indications : RGO, ulcère, H. pylori, prévention sous AINS, hémorragie digestive","Au long cours : hypomagnésémie, carence en B12, fractures, C. difficile ; **réévaluer l'indication**"],"err":[],"q":[{"q":"Quand faut-il prendre un IPP ?","o":["Au coucher après le repas","Le matin à jeun, 15 à 30 minutes avant le petit-déjeuner","Au milieu du repas de midi"],"a":1,"e":"Les pompes à protons sont activées par le repas : l'IPP doit être présent dans le sang à ce moment."},{"q":"Quel IPP préférer chez un patient sous clopidogrel ?","o":["L'oméprazole","Le pantoprazole","L'ésoméprazole"],"a":1,"e":"Oméprazole et ésoméprazole diminuent l'activation du clopidogrel ; le pantoprazole interfère peu."}],"f":["digestifs-med","m:antiacides","m:ains"]},
{"n":"Antiacides, alginates et pansements gastriques","i":"antiacides","s":"gastro","nn":["Antiacides","Pansements gastriques","Alginate","Gaviscon","Smecta"],"d":["Les **antiacides** neutralisent l'acide déjà présent dans l'estomac, les **alginates** forment une barrière contre le reflux, les **pansements gastriques** tapissent la muqueuse. Ils soulagent rapidement les brûlures ponctuelles mais n'ont pas d'effet durable."],"ma":["Les antiacides (hydroxydes d'aluminium et de magnésium, carbonates) **neutralisent** l'acide. Les **alginates** forment au contact de l'acide un **gel qui flotte** sur le contenu gastrique (radeau) et empêche le reflux. Les **pansements** (diosmectite, sucralfate) adhèrent à la muqueuse et la protègent."],"sch":{"k":"ipp","cap":"Antiacides et alginates agissent dans la lumière de l'estomac, sans bloquer la sécrétion."},"m":[{"dci":"Hydroxydes d'aluminium et de magnésium","br":"Maalox®, Xolaam®","pr":"antiacides"},{"dci":"Alginate de sodium + bicarbonate","br":"Gaviscon®","pr":"radeau anti-reflux"},{"dci":"Diosmectite","br":"Smecta®","pr":"pansement digestif, diarrhée"},{"dci":"Sucralfate","br":"Ulcar®, Keal®","pr":"pansement gastrique"}],"ind":["Brûlures et régurgitations ponctuelles (reflux occasionnel), grossesse","Douleurs épigastriques en complément d'un traitement de fond","Diarrhée aiguë (diosmectite, en complément de la réhydratation)"],"ci":["Insuffisance rénale sévère (aluminium, magnésium : accumulation)","Régime sans sel strict (alginates riches en sodium)","Diosmectite : constipation sévère, occlusion"],"ef":["**Constipation** (aluminium) ou **diarrhée** (magnésium)","Ballonnements"],"eg":["Accumulation d'aluminium ou de magnésium chez l'insuffisant rénal","Occlusion (fortes doses chez la personne âgée alitée)"],"it":[],"v":[],"sc":["Efficacité sur les symptômes, transit","Persistance ou aggravation des symptômes (consultation)"],"sb":["Aucune"],"p":[],"edu":[],"cat":[],"r":["Soulagent vite, sans traiter la cause","**Espacer de 2 heures** des autres médicaments (absorption diminuée)","Après les repas et au coucher ; prudence chez l'insuffisant rénal"],"err":[],"q":[],"f":["digestifs-med","m:ipp"],"_l":1},
{"n":"Antiémétiques","i":"antiemetiques","s":"gastro","nn":["Antiémétiques antagonistes dopaminergiques","Antagonistes des récepteurs 5-HT3","Antagonistes des récepteurs NK1","Prokinétiques","Antiemétiques de chimiothérapie","Métoclopramide","Ondansétron"],"d":["Les **antiémétiques** préviennent et traitent les **nausées et vomissements** : après une anesthésie, sous chimiothérapie, lors d'une gastro-entérite, en soins palliatifs. Le choix dépend de la cause."],"ma":["Les vomissements sont déclenchés par le **centre du vomissement** du tronc cérébral, stimulé par la dopamine, la sérotonine (5-HT3), la substance P (NK1), l'histamine et l'acétylcholine. Chaque antiémétique bloque un de ces récepteurs : **antidopaminergiques** (métoclopramide, dompéridone, métopimazine), **anti-5-HT3** (ondansétron), **anti-NK1** (aprépitant). Le métoclopramide et la dompéridone accélèrent aussi la vidange gastrique (**prokinétiques**)."],"sch":null,"m":[{"dci":"Métoclopramide","br":"Primpéran®","pr":"antidopaminergique, prokinétique"},{"dci":"Dompéridone","br":"Motilium®","pr":"antidopaminergique périphérique"},{"dci":"Métopimazine","br":"Vogalène®","pr":"antidopaminergique"},{"dci":"Ondansétron, granisétron","br":"Zophren®, Kytril®","pr":"anti-5-HT3 (chimiothérapie, post-opératoire)"},{"dci":"Aprépitant","br":"Emend®","pr":"anti-NK1 (chimiothérapie très émétisante)"},{"dci":"Dexaméthasone, halopéridol","br":"Dectancyl®, Haldol®","pr":"chimiothérapie, soins palliatifs"}],"ind":["Nausées et vomissements post-opératoires","**Nausées et vomissements de la chimiothérapie** (protocoles associant anti-5-HT3, anti-NK1 et corticoïde)","Gastroparésie (prokinétiques), migraine","Soins palliatifs (halopéridol)"],"ci":["Métoclopramide : **maladie de Parkinson**, antécédent de dyskinésie, occlusion, hémorragie digestive, **enfant de moins de 1 an**, phéochromocytome","Dompéridone : **allongement du QT**, troubles du rythme, insuffisance hépatique","Ondansétron : QT long congénital"],"ef":["Somnolence, fatigue","Ondansétron : **constipation**, céphalées","Métoclopramide : diarrhée"],"eg":["**Syndromes extrapyramidaux** (dyskinésie aiguë : torticolis, mouvements anormaux des yeux, de la langue ; akathisie), surtout chez l'enfant et le jeune ; **dyskinésies tardives**","**Troubles du rythme** (QT long : dompéridone, ondansétron)","Syndrome malin des neuroleptiques (rare)"],"it":[],"v":[],"sc":["Nombre de vomissements, nausées (échelle), hydratation, diurèse","**Mouvements anormaux** (métoclopramide), agitation","Transit (ondansétron), pouls"],"sb":["Ionogramme si vomissements importants (hypokaliémie, déshydratation) ; ECG si risque de QT long"],"p":[],"edu":[],"cat":[],"r":["Antidopaminergiques, anti-5-HT3, anti-NK1, corticoïdes : selon la cause","Métoclopramide : **5 jours maximum**, **contre-indiqué dans la maladie de Parkinson**, effets extrapyramidaux","Dompéridone, ondansétron : **QT long** ; ondansétron : constipation"],"err":[],"q":[],"f":["chimio","s:chimiotherapie","m:chimio"],"_l":1},
{"n":"Antispasmodiques digestifs","i":"antispasmodiques","s":"gastro","nn":["Antispasmodiques digestifs","Antispasmodiques","Phloroglucinol","Spasfon"],"d":["Les **antispasmodiques** soulagent les **douleurs digestives de type spasme** (coliques, syndrome de l'intestin irritable), mais aussi certaines douleurs urinaires, biliaires ou gynécologiques. Ils sont très utilisés et généralement bien tolérés."],"ma":["Ils relâchent les muscles lisses du tube digestif : **action musculotrope** directe (phloroglucinol, trimébutine, mébévérine) ou **anticholinergique** (tiémonium, scopolamine)."],"sch":null,"m":[{"dci":"Phloroglucinol","br":"Spasfon®, Spasfon Lyoc®","pr":"musculotrope ; oral, lyophilisat, IV"},{"dci":"Trimébutine","br":"Débridat®","pr":"régulateur de la motricité (intestin irritable)"},{"dci":"Mébévérine, pinavérium","br":"Duspatalin®, Dicetel®","pr":"intestin irritable"},{"dci":"Tiémonium","br":"Viscéralgine®","pr":"anticholinergique"}],"ind":["Douleurs spasmodiques digestives, **syndrome de l'intestin irritable**","Coliques hépatiques et néphrétiques (en complément), douleurs gynécologiques"],"ci":["Anticholinergiques (tiémonium) : glaucome à angle fermé, adénome de prostate, iléus","Hypersensibilité"],"ef":["Réactions cutanées (rares)","Anticholinergiques : bouche sèche, constipation, troubles visuels"],"eg":["Réaction allergique (phloroglucinol IV, rare)","Anticholinergiques : rétention urinaire, confusion (personne âgée)"],"it":[],"v":[],"sc":["Douleur (localisation, intensité, évolution)","Signes de gravité devant une douleur abdominale : fièvre, défense, vomissements, arrêt des gaz"],"sb":["Aucune"],"p":[],"edu":[],"cat":[],"r":["Relâchent le muscle lisse : musculotropes (phloroglucinol) ou anticholinergiques","Ne doivent pas masquer une urgence abdominale","Personne âgée : préférer les musculotropes"],"err":[],"q":[],"f":["m:anticholinergiques"],"_l":1},
{"n":"Antidiarrhéiques","i":"antidiarrheiques","s":"gastro","nn":["Antidiarrhéiques","Antisécrétoires intestinaux","Lopéramide","Racécadotril","Imodium"],"d":["Les **antidiarrhéiques** diminuent la fréquence des selles. Ils ne traitent pas la cause et ne remplacent **jamais la réhydratation**, priorité absolue en cas de diarrhée, surtout chez le nourrisson et la personne âgée."],"ma":["Le **lopéramide** ralentit le transit (agoniste opioïde périphérique, sans effet sur le cerveau aux doses usuelles). Le **racécadotril** diminue la sécrétion d'eau et d'électrolytes par l'intestin. La **diosmectite** adsorbe l'eau et les toxines."],"sch":null,"m":[{"dci":"Lopéramide","br":"Imodium®","pr":"ralentisseur du transit"},{"dci":"Racécadotril","br":"Tiorfan®","pr":"antisécrétoire (adulte et enfant)"},{"dci":"Diosmectite","br":"Smecta®","pr":"adsorbant"},{"dci":"Solutés de réhydratation orale","br":"Adiaril®, Fanolyte®","pr":"prévention de la déshydratation (voir pédiatrie)"}],"ind":["**Diarrhée aiguë** non compliquée de l'adulte (en complément de la réhydratation)","Diarrhée chronique fonctionnelle, iléostomie à fort débit (lopéramide)"],"ci":["Lopéramide : **diarrhée fébrile ou sanglante** (infection invasive), **colite à C. difficile**, poussée de MICI, enfant de moins de 2 ans","Racécadotril : hypersensibilité"],"ef":["Constipation, ballonnements, douleurs abdominales"],"eg":["Lopéramide : **iléus**, **mégacôlon toxique** (en cas d'infection invasive), troubles du rythme en cas de surdosage massif (mésusage)","Racécadotril : angio-œdème (rare, surtout avec les IEC)"],"it":[],"v":[],"sc":["Nombre et aspect des selles (sang, glaires), fièvre, douleurs","**Signes de déshydratation** : soif, pli cutané, perte de poids, diurèse, hypotension, tachycardie"],"sb":["Ionogramme et créatinine si diarrhée sévère ; coproculture, recherche de C. difficile si fièvre, sang ou antibiotiques récents"],"p":[],"edu":[],"cat":[],"r":["**Réhydratation d'abord** ; l'antidiarrhéique ne traite que le symptôme","Lopéramide **contre-indiqué** si fièvre, sang dans les selles, C. difficile, enfant < 2 ans","Surveiller l'hydratation, surtout aux âges extrêmes"],"err":[],"q":[],"f":["m:sro","m:laxatifs"],"_l":1},
{"n":"Laxatifs","i":"laxatifs","s":"gastro","nn":["Laxatifs osmotiques","Laxatifs de lest","Laxatifs stimulants","Laxatifs lubrifiants","Laxatifs rectaux","Lavements évacuateurs","Traitements des troubles du transit","Macrogol","Lactulose"],"d":["Les **laxatifs** traitent la **constipation**, fréquente chez la personne âgée, la femme enceinte, le patient alité, sous **opioïdes** ou sous anticholinergiques. Ils complètent toujours les mesures hygiéno-diététiques (eau, fibres, activité)."],"ma":["Plusieurs mécanismes : les **osmotiques** (macrogol, lactulose) retiennent l'eau dans l'intestin ; les **laxatifs de lest** (psyllium, ispaghul) augmentent le volume des selles ; les **stimulants** (bisacodyl, séné) augmentent les contractions intestinales ; les **lubrifiants** (huile de paraffine) facilitent le glissement ; les **laxatifs rectaux** déclenchent le réflexe d'exonération."],"sch":null,"m":[{"dci":"Macrogol","br":"Movicol®, Forlax®, Transipeg®","pr":"osmotique, référence"},{"dci":"Lactulose","br":"Duphalac®","pr":"osmotique (aussi encéphalopathie hépatique)"},{"dci":"Ispaghul, psyllium","br":"Spagulax®, Psylia®","pr":"de lest"},{"dci":"Bisacodyl, séné","br":"Dulcolax®, Contalax®","pr":"stimulants (courte durée)"},{"dci":"Huile de paraffine","br":"Lansoÿl®, Lubentyl®","pr":"lubrifiant"},{"dci":"Suppositoires, microlavements","br":"Eductyl®, Microlax®, Normacol®","pr":"rectaux"}],"ind":["**Constipation** fonctionnelle, de la personne âgée, de la grossesse","**Constipation sous opioïdes** (laxatif systématique dès la première prise)","Préparation à une coloscopie (macrogol à forte dose), fécalome (lavements)","Encéphalopathie hépatique (lactulose)"],"ci":["**Occlusion intestinale**, douleurs abdominales inexpliquées, MICI en poussée","Laxatifs de lest : sténose digestive, fécalome, patient alité qui boit peu","Huile de paraffine : **troubles de la déglutition**, patient alité (risque de **pneumopathie d'inhalation**)"],"ef":["Ballonnements, flatulences (osmotiques, lest)","Douleurs abdominales, diarrhée (stimulants)","Suintement anal (huile de paraffine)"],"eg":["**Déshydratation et hypokaliémie** (abus de laxatifs stimulants, fortes doses)","**Pneumopathie lipidique** (huile de paraffine inhalée)","Occlusion (laxatifs de lest sans hydratation suffisante)"],"it":[],"v":[],"sc":["**Transit** (fréquence, consistance des selles : échelle de Bristol), ballonnements, douleurs","Hydratation, alimentation, mobilité","Signes d'occlusion ou de fécalome (arrêt des matières et des gaz, vomissements, fausse diarrhée chez la personne âgée)"],"sb":["Kaliémie si abus de laxatifs ou diarrhée importante"],"p":[],"edu":[],"cat":[],"r":["Osmotiques (macrogol) en première intention ; stimulants en cure courte","**Laxatif systématique sous opioïdes**","Huile de paraffine : jamais au coucher ni chez le patient qui fait des fausses routes","Contre-indiqués en cas d'occlusion ; fausse diarrhée = fécalome"],"err":[],"q":[],"f":["digestifs-med","m:opio-forts","m:cirrhose"],"_l":1},
{"n":"Traitements des maladies inflammatoires chroniques de l'intestin (MICI)","i":"mici","s":"gastro","nn":["Traitements des maladies inflammatoires chroniques de l'intestin","Aminosalicylés","Corticoïdes digestifs","Immunosuppresseurs digestifs","Biothérapies digestives","Mésalazine","Maladie de Crohn","Rectocolite hémorragique"],"d":["La **maladie de Crohn** et la **rectocolite hémorragique** évoluent par **poussées** (diarrhée, douleurs, sang dans les selles, amaigrissement) et rémissions. Le traitement vise à **contrôler les poussées** puis à **maintenir la rémission** et éviter les complications."],"ma":["Les **aminosalicylés** (mésalazine) ont un effet anti-inflammatoire local sur la muqueuse. Les **corticoïdes** traitent les poussées. Les **immunosuppresseurs** (azathioprine, méthotrexate) et les **biothérapies** (anti-TNF, anti-intégrines, anti-IL12/23) freinent la réaction immunitaire responsable de l'inflammation."],"sch":null,"m":[{"dci":"Mésalazine","br":"Pentasa®, Rowasa®, Fivasa®","pr":"oral, suppositoires, lavements (rectocolite)"},{"dci":"Budésonide, prednisone","br":"Entocort®, Cortancyl®","pr":"poussées"},{"dci":"Azathioprine","br":"Imurel®","pr":"immunosuppresseur d'entretien"},{"dci":"Infliximab, adalimumab","br":"Rémicade® (IV), Humira® (SC)","pr":"anti-TNF"},{"dci":"Védolizumab, ustékinumab","br":"Entyvio®, Stelara®","pr":"biothérapies"}],"ind":["**Rectocolite hémorragique** : mésalazine en première intention","**Maladie de Crohn** modérée à sévère : corticoïdes en poussée, immunosuppresseurs, biothérapies","Maintien de la rémission, cicatrisation de la muqueuse"],"ci":["Mésalazine : insuffisance rénale sévère, allergie aux salicylés","Immunosuppresseurs et biothérapies : **infection évolutive**, tuberculose non traitée, cancer récent","Azathioprine : déficit en TPMT (toxicité médullaire), association à l'allopurinol"],"ef":["Mésalazine : céphalées, troubles digestifs","Azathioprine : nausées, chute de cheveux","Biothérapies : réaction à la perfusion ou au point d'injection"],"eg":["**Infections** (opportunistes, tuberculose), **cancers** (peau, lymphomes) sous immunosuppresseurs et biothérapies","Azathioprine : **aplasie médullaire**, pancréatite, hépatite","Mésalazine : néphrite interstitielle, pancréatite"],"it":[],"v":[],"sc":["Nombre de selles, sang, douleurs, poids, fièvre","Signes d'infection, lésions cutanées","Pendant une perfusion d'infliximab : constantes, signes allergiques"],"sb":["**NFS, bilan hépatique** (azathioprine), créatinine (mésalazine), CRP, calprotectine fécale ; bilan avant biothérapie (tuberculose, hépatites, VIH)"],"p":[],"edu":[],"cat":[],"r":["Mésalazine (RCH), corticoïdes (poussée), azathioprine, biothérapies (anti-TNF…)","Immunosuppression : **infections, cancers** ; bilan infectieux avant biothérapie ; pas de vaccin vivant","Azathioprine : **NFS** ; jamais avec l'allopurinol sans adaptation","Arrêt du tabac dans la maladie de Crohn"],"err":[],"q":[],"f":["m:biotherapies","m:corticoides"],"_l":1},
{"n":"Traitements de la cirrhose et de ses complications","i":"cirrhose","s":"gastro","nn":["Traitements de l'encéphalopathie hépatique","Traitements de l'ascite","Traitements des hémorragies digestives","Acide ursodésoxycholique","Terlipressine","Rifaximine"],"d":["La **cirrhose** expose à des complications graves : **ascite**, **hémorragie digestive** par rupture de varices œsophagiennes, **encéphalopathie hépatique**, infections. Leur traitement associe des médicaments spécifiques et la prise en charge de la cause (alcool, hépatites)."],"ma":["Contre l'**encéphalopathie**, le **lactulose** acidifie le côlon et accélère le transit (moins d'ammoniac absorbé), la **rifaximine** diminue les bactéries productrices d'ammoniac. Contre l'**ascite**, la **spironolactone** et le **furosémide** éliminent le sel ; l'**albumine** compense les grandes ponctions. Contre l'**hémorragie**, la **terlipressine** ou l'octréotide resserrent les vaisseaux digestifs (moins de pression portale) ; le **propranolol** prévient les récidives."],"sch":null,"m":[{"dci":"Lactulose","br":"Duphalac®","pr":"encéphalopathie : 2 à 3 selles molles par jour"},{"dci":"Rifaximine","br":"Tixtar®","pr":"prévention des récidives d'encéphalopathie"},{"dci":"Spironolactone + furosémide","br":"Aldactone®, Lasilix®","pr":"ascite"},{"dci":"Albumine 20 %","br":"Albunorm®, Vialebex®","pr":"ponction d'ascite > 5 L, infection du liquide d'ascite"},{"dci":"Terlipressine, octréotide","br":"Glypressine®, Sandostatine®","pr":"hémorragie par rupture de varices"},{"dci":"Propranolol","br":"Avlocardyl®","pr":"prévention des hémorragies"},{"dci":"Acide ursodésoxycholique","br":"Delursan®, Ursolvan®","pr":"cholangite biliaire primitive, calculs biliaires"}],"ind":["**Encéphalopathie hépatique** (confusion, astérixis : tremblement des mains en battement d'ailes)","**Ascite** : régime pauvre en sel, diurétiques, ponctions évacuatrices","**Hémorragie digestive** par hypertension portale (terlipressine, IPP, antibioprophylaxie, endoscopie)","Prévention de la rupture de varices (propranolol, ligature)"],"ci":["Terlipressine : maladie coronaire, insuffisance cardiaque, artériopathie","Diurétiques : hyponatrémie sévère, insuffisance rénale aiguë","**Sédatifs** (benzodiazépines) : à éviter (précipitent l'encéphalopathie)"],"ef":["Lactulose : ballonnements, diarrhée","Diurétiques : crampes, gynécomastie (spironolactone)","Terlipressine : pâleur, douleurs abdominales, hypertension"],"eg":["Diurétiques : **insuffisance rénale**, **hyponatrémie**, hyperkaliémie, encéphalopathie","Terlipressine : **ischémie** (cœur, intestin, peau), hyponatrémie","Lactulose en excès : déshydratation, hypernatrémie"],"it":[],"v":[],"sc":["**Conscience** (confusion, inversion du rythme veille-sommeil, astérixis)","**Poids quotidien**, périmètre abdominal, diurèse, œdèmes","Signes d'hémorragie (hématémèse, méléna, pouls, tension), transit"],"sb":["**Natrémie, kaliémie, créatinine**, bilan hépatique, TP, albuminémie, NFS ; analyse du liquide d'ascite"],"p":[],"edu":[],"cat":[],"r":["Encéphalopathie : **lactulose** (2 à 3 selles molles par jour) ± rifaximine ; éviter les sédatifs","Ascite : **sel limité**, spironolactone ± furosémide, albumine si grande ponction","Hémorragie : terlipressine, IPP, antibiotique, endoscopie ; propranolol en prévention","**Pas d'AINS**, paracétamol limité, arrêt de l'alcool"],"err":[],"q":[],"f":["m:antialdo","m:remplissage","m:laxatifs"],"_l":1},
{"n":"Insulines","i":"insulines","s":"diab","nn":["Insulines rapides","Insulines ultrarapides","Insulines intermédiaires","Insulines lentes","Insulines ultralentes","Insulines prémélangées","Insulines pédiatriques","Insulinothérapie"],"d":["L'**insuline** est indispensable dans le **diabète de type 1** (le pancréas n'en produit plus) et souvent nécessaire dans le **diabète de type 2** évolué, le diabète gestationnel, et à l'hôpital (hyperglycémie, corticoïdes, nutrition artificielle).","C'est un **médicament à haut risque** : une erreur de dose ou d'insuline peut provoquer une hypoglycémie grave. On distingue les insulines selon leur **profil d'action**."],"ma":["L'insuline fait **entrer le glucose dans les cellules** (muscles, tissu adipeux), favorise son stockage dans le foie et freine la production hépatique de glucose : la glycémie baisse. Elle fait aussi entrer le potassium dans les cellules.","Le schéma **basal-bolus** imite la sécrétion normale : une insuline **lente** couvre les besoins de base sur 24 h, une insuline **rapide** couvre chaque repas."],"sch":{"k":"insuline","cap":"Profil d'action des insulines : une lente pour le fond, des rapides pour les repas."},"m":[{"dci":"Insulines ultrarapides : asparte, lispro, glulisine","br":"NovoRapid®, Fiasp®, Humalog®, Apidra®","pr":"début 10-15 min, pic 1 h, durée 3-5 h"},{"dci":"Insuline rapide humaine","br":"Actrapid®, Umuline rapide®","pr":"**seule utilisée en IV** (pousse-seringue), début 30 min"},{"dci":"Insuline intermédiaire NPH","br":"Insulatard®, Umuline NPH®","pr":"**aspect trouble** : rouler avant usage ; durée 12-16 h"},{"dci":"Insulines lentes : glargine, détémir","br":"Lantus®, Abasaglar®, Toujeo® (U300), Levemir®","pr":"environ 24 h, sans pic"},{"dci":"Insuline dégludec","br":"Tresiba®","pr":"ultralente (plus de 40 h)"},{"dci":"Prémélangées","br":"NovoMix® 30, Humalog Mix®","pr":"rapide + intermédiaire, à rouler"}],"ind":["**Diabète de type 1** (à vie)","**Diabète de type 2** en échec des antidiabétiques oraux, à l'hôpital, sous corticoïdes","**Diabète gestationnel** non équilibré par le régime","**Acidocétose**, hyperglycémie hyperosmolaire (insuline IV)","Hyperkaliémie (avec du glucose)"],"ci":["**Hypoglycémie** en cours","Hypersensibilité à un excipient (exceptionnelle)"],"ef":["**Hypoglycémie** (effet indésirable le plus fréquent)","**Prise de poids**","**Lipodystrophies** (bosses ou creux) si l'on pique toujours au même endroit"],"eg":["**Hypoglycémie sévère** : convulsions, coma","**Hypokaliémie** (insuline IV, traitement de l'acidocétose)","Erreur d'insuline ou de dose (unités) : accident grave"],"it":["**Bêtabloquants** : masquent les signes d'hypoglycémie","**Corticoïdes**, diurétiques thiazidiques, antipsychotiques : hyperglycémie (besoins augmentés)","Alcool : hypoglycémies retardées"],"v":["**SC** au stylo ou à la seringue graduée en unités, ou par **pompe** ; IV uniquement l'insuline rapide humaine, au pousse-seringue, avec protocole et glycémies horaires","**Sites** : abdomen (absorption rapide), cuisses, bras, fesses ; **rotation des sites**, aiguille de 4 à 5 mm, souvent sans pli, maintenir **10 secondes** avant de retirer l'aiguille","**Glycémie capillaire avant l'injection** ; insuline rapide **juste avant le repas** (ultrarapide) ou 15 à 30 minutes avant (rapide humaine) ; ne pas l'injecter si le patient ne mange pas sans avis","**Concentrations** : U100 le plus souvent, U200 ou **U300** pour certains stylos : **ne jamais prélever l'insuline d'un stylo avec une seringue**","**Conservation** : flacons et stylos neufs au **réfrigérateur (2 à 8 °C)**, jamais congelés ; en cours d'utilisation à température ambiante (moins de 25-30 °C) pendant **4 semaines** ; noter la date d'ouverture"],"sc":["**Glycémies capillaires** (avant les repas, au coucher, selon le protocole), signes d'hypoglycémie","**Sites d'injection** (lipodystrophies)","Alimentation réelle (repas pris ou non), poids"],"sb":["**HbA1c** tous les 3 mois, kaliémie sous insuline IV, cétonémie ou cétonurie si glycémie > 2,5 g/L (type 1)"],"p":["Personne âgée : objectifs glycémiques moins stricts, prévention des hypoglycémies (chutes, confusion)","Enfant : doses très faibles, stylos à demi-unités, éducation des parents et de l'école (PAI)","Grossesse : insuline seule autorisée pour le diabète ; objectifs stricts, besoins variables","Insuffisance rénale : besoins diminués, hypoglycémies plus fréquentes"],"edu":["**Autosurveillance glycémique**, adaptation des doses, technique d'injection, rotation des sites","Reconnaître et traiter une **hypoglycémie** (sucre sur soi), informer l'entourage, glucagon","Activité physique, alcool, maladie : adapter (ne jamais arrêter l'insuline lente dans le type 1)","Conservation, élimination des aiguilles dans un collecteur"],"cat":["**Hypoglycémie** : resucrage immédiat (15 g de sucre si conscient, glucose IV ou glucagon si inconscient), contrôle à 15 minutes","Glycémie élevée chez un diabétique de type 1 : recherche de corps cétoniques, prévenir","Erreur de dose ou d'insuline : prévenir immédiatement, glycémies rapprochées, déclaration"],"r":["Lente = fond (24 h) ; ultrarapide = repas ; seule la **rapide humaine en IV**","**Glycémie avant injection**, rotation des sites, 10 secondes avant de retirer l'aiguille","**Jamais de seringue dans un stylo** (U300) ; conservation au froid, 4 semaines à température ambiante une fois ouverte","Risque principal : **hypoglycémie**"],"err":["Injecter l'insuline rapide alors que le patient ne mange pas","Prélever l'insuline d'un stylo U300 avec une seringue U100"],"q":[{"q":"Quelle insuline peut être administrée par voie IV ?","o":["L'insuline glargine","L'insuline rapide humaine (Actrapid®)","L'insuline NPH"],"a":1,"e":"Seule l'insuline rapide humaine (et certaines ultrarapides selon les protocoles) s'utilise en IV ; jamais les lentes ni la NPH."},{"q":"Combien de temps un stylo d'insuline entamé se conserve-t-il à température ambiante ?","o":["24 heures","Environ 4 semaines","6 mois"],"a":1,"e":"Une fois entamé, le stylo se garde à température ambiante environ 4 semaines ; noter la date d'ouverture."}],"f":["insuline-f","insuline","s:insuline-admin","s:education-insuline","s:hypoglycemie","m:hypoglycemie-ttt"]},
{"n":"Metformine (biguanides)","i":"metformine","s":"diab","nn":["Biguanides","Metformine","Glucophage"],"d":["La **metformine** est le **traitement de première intention du diabète de type 2**. Elle ne provoque **pas d'hypoglycémie** utilisée seule, ne fait pas prendre de poids et réduit les complications cardiovasculaires."],"ma":["Elle diminue la **production de glucose par le foie** et améliore la sensibilité des muscles à l'insuline (moins d'insulinorésistance). Elle ne stimule pas la sécrétion d'insuline."],"sch":{"k":"antidiab","cap":"La metformine agit surtout sur le foie et améliore l'action de l'insuline sur les muscles."},"m":[{"dci":"Metformine","br":"Glucophage®, Stagid®","pr":"500, 850, 1000 mg"},{"dci":"Associations","br":"Janumet®, Synjardy®, Xigduo®","pr":"avec une gliptine ou une gliflozine"}],"ind":["**Diabète de type 2**, dès le diagnostic, avec les mesures hygiéno-diététiques","Associée aux autres antidiabétiques et à l'insuline"],"ci":["**Insuffisance rénale sévère** (DFG < 30 mL/min) ; dose réduite entre 30 et 45","**Situations à risque d'acidose lactique** : déshydratation, infection sévère, état de choc, insuffisance cardiaque ou respiratoire décompensée, insuffisance hépatique, alcoolisme","**Injection de produit de contraste iodé** et chirurgie : suspension temporaire (selon la fonction rénale)"],"ef":["**Troubles digestifs** (diarrhée, nausées, douleurs, goût métallique), surtout au début","Carence en **vitamine B12** au long cours"],"eg":["**Acidose lactique** (rare mais grave) : douleurs abdominales, crampes, vomissements, polypnée, malaise, chez un patient insuffisant rénal ou en situation aiguë"],"it":[],"v":[],"sc":["Tolérance digestive, glycémies","Signes de déshydratation ou d'acidose (vomissements, crampes, polypnée)"],"sb":["**Créatinine (DFG)** au moins une fois par an (plus souvent chez la personne âgée), **HbA1c**, vitamine B12"],"p":[],"edu":[],"cat":[],"r":["**Première intention** du diabète de type 2 ; **pas d'hypoglycémie** seule","Pendant les repas ; troubles digestifs au début","Contre-indiquée si **DFG < 30** ; suspendre avant **produit de contraste** iodé et en cas de déshydratation","Acidose lactique rare mais grave"],"err":[],"q":[],"f":["ado","m:sulfamides-hypo","m:sglt2"],"_l":1},
{"n":"Sulfamides hypoglycémiants et glinides","i":"sulfamides-hypo","s":"diab","nn":["Sulfamides hypoglycémiants","Glinides","Gliclazide","Répaglinide"],"d":["Les **sulfamides hypoglycémiants** et les **glinides** stimulent le pancréas pour qu'il sécrète plus d'insuline. Efficaces et peu coûteux, ils exposent au risque principal d'**hypoglycémie**, parfois prolongée, surtout chez la personne âgée."],"ma":["Ils se fixent sur les cellules bêta du pancréas et déclenchent la **sécrétion d'insuline**, quelle que soit la glycémie (d'où les hypoglycémies). Les glinides agissent plus vite et moins longtemps."],"sch":{"k":"antidiab","cap":"Sulfamides et glinides stimulent la sécrétion d'insuline par le pancréas."},"m":[{"dci":"Gliclazide","br":"Diamicron®","pr":"sulfamide (forme LP une fois par jour)"},{"dci":"Glimépiride","br":"Amarel®","pr":"sulfamide"},{"dci":"Glibenclamide","br":"Daonil®","pr":"sulfamide (risque d'hypoglycémie plus élevé)"},{"dci":"Répaglinide","br":"Novonorm®","pr":"glinide, avant chaque repas"}],"ind":["**Diabète de type 2** en complément ou en remplacement de la metformine"],"ci":["**Insuffisance rénale ou hépatique sévère**","Diabète de type 1, acidocétose, grossesse, allaitement","Allergie aux sulfamides ; association miconazole"],"ef":["**Hypoglycémies**","**Prise de poids**","Troubles digestifs"],"eg":["**Hypoglycémie sévère et prolongée** (personne âgée, insuffisant rénal, repas sauté, alcool) : récidive possible pendant plusieurs heures","Réactions cutanées, troubles hématologiques (rares)"],"it":[],"v":[],"sc":["**Glycémies capillaires**, signes d'hypoglycémie, poids","Prise alimentaire réelle (patient hospitalisé, personne âgée qui mange peu)"],"sb":["HbA1c, créatinine, bilan hépatique"],"p":[],"edu":[],"cat":[],"r":["Stimulent la sécrétion d'insuline : **hypoglycémies** (prolongées chez la personne âgée)","Glinide : **pas de repas, pas de comprimé**","Interactions : miconazole, fluconazole, clarithromycine ; bêtabloquants masquent les signes"],"err":[],"q":[],"f":["ado","m:metformine","m:hypoglycemie-ttt"],"_l":1},
{"n":"Incrétines : gliptines et analogues du GLP-1","i":"incretines","s":"diab","nn":["Inhibiteurs de la DPP-4","Analogues du GLP-1","Agonistes doubles GIP/GLP-1","Gliptines","Sémaglutide","Ozempic","Tirzépatide"],"d":["Les **incrétines** sont des hormones intestinales (GLP-1, GIP) qui stimulent la sécrétion d'insuline **seulement quand la glycémie est élevée**. Les **gliptines** (oral) prolongent leur effet ; les **analogues du GLP-1** (injectables) les imitent, font **perdre du poids** et protègent le cœur et le rein."],"ma":["Les **analogues du GLP-1** stimulent l'insuline et freinent le glucagon en fonction de la glycémie, **ralentissent la vidange gastrique** et augmentent la **satiété** (cerveau). Les **gliptines** bloquent l'enzyme DPP-4 qui détruit le GLP-1 naturel. Le **tirzépatide** stimule à la fois les récepteurs GIP et GLP-1."],"sch":{"k":"antidiab","cap":"Les incrétines agissent sur le pancréas, l'estomac et le cerveau."},"m":[{"dci":"Sitagliptine, vildagliptine, saxagliptine","br":"Januvia®, Galvus®, Onglyza®","pr":"gliptines (oral)"},{"dci":"Sémaglutide","br":"Ozempic® (SC hebdomadaire), Rybelsus® (oral)","pr":"analogue du GLP-1"},{"dci":"Dulaglutide, liraglutide","br":"Trulicity® (hebdomadaire), Victoza® (quotidien)","pr":"analogues du GLP-1"},{"dci":"Tirzépatide","br":"Mounjaro®","pr":"agoniste GIP/GLP-1 (hebdomadaire)"}],"ind":["**Diabète de type 2** en association à la metformine, notamment en cas d'obésité ou de maladie cardiovasculaire (analogues du GLP-1)","Obésité sévère (certaines molécules et dosages spécifiques)"],"ci":["Diabète de type 1, acidocétose","Antécédent de **pancréatite**","Analogues du GLP-1 : antécédent personnel ou familial de cancer médullaire de la thyroïde ; rétinopathie diabétique sévère (sémaglutide : prudence)"],"ef":["Analogues du GLP-1 : **nausées, vomissements, diarrhée**, constipation, perte d'appétit (surtout au début)","Gliptines : céphalées, rhinopharyngite","Réactions au point d'injection"],"eg":["**Pancréatite aiguë** (douleur abdominale intense irradiant dans le dos)","Déshydratation et insuffisance rénale (vomissements importants)","Lithiase biliaire ; aggravation d'une rétinopathie (baisse rapide de la glycémie)","Hypoglycémie si association à l'insuline ou à un sulfamide (pas seuls)"],"it":[],"v":[],"sc":["Tolérance digestive, poids, hydratation","**Douleurs abdominales** (pancréatite)","Glycémies (si associés à l'insuline ou à un sulfamide)"],"sb":["HbA1c, créatinine, lipase si douleur abdominale"],"p":[],"edu":[],"cat":[],"r":["Stimulent l'insuline **seulement si la glycémie est élevée** : pas d'hypoglycémie seuls","Analogues du GLP-1 : perte de poids, protection cardiovasculaire, **nausées** ; injection quotidienne ou **hebdomadaire**","**Pancréatite** à reconnaître ; contre-indiqués pendant la grossesse"],"err":[],"q":[],"f":["ado","m:metformine","m:sglt2"],"_l":1},
{"n":"Gliflozines (inhibiteurs du SGLT2)","i":"sglt2","s":"diab","nn":["Inhibiteurs du SGLT2","Gliflozines","Dapagliflozine","Empagliflozine"],"d":["Les **gliflozines** font éliminer le glucose dans les urines. Au-delà du diabète de type 2, elles **protègent le cœur et le rein** : elles sont devenues un traitement majeur de l'**insuffisance cardiaque** et de la **maladie rénale chronique**, même chez les non-diabétiques."],"ma":["Elles bloquent le transporteur **SGLT2** du tube contourné proximal du rein, qui réabsorbe normalement le glucose filtré : le glucose (et un peu de sodium et d'eau) part dans les urines."],"sch":{"k":"antidiab","cap":"Les gliflozines font éliminer le glucose par le rein."},"m":[{"dci":"Dapagliflozine","br":"Forxiga®","pr":"diabète, insuffisance cardiaque, maladie rénale chronique"},{"dci":"Empagliflozine","br":"Jardiance®","pr":"diabète, insuffisance cardiaque, maladie rénale chronique"},{"dci":"Canagliflozine","br":"Invokana®","pr":"diabète"}],"ind":["**Diabète de type 2** (surtout avec maladie cardiovasculaire ou rénale)","**Insuffisance cardiaque** (quelle que soit la fraction d'éjection)","**Maladie rénale chronique**"],"ci":["Diabète de type 1 (risque d'acidocétose)","**Déshydratation**, hypovolémie","Infections génitales ou urinaires récidivantes (prudence)"],"ef":["**Infections génitales** (mycoses vulvaires, balanites) et urinaires","**Mictions plus fréquentes**, soif","Légère baisse de la tension"],"eg":["**Acidocétose euglycémique** (acidocétose avec une glycémie peu élevée : nausées, vomissements, douleurs abdominales, fatigue, polypnée), surtout en cas de jeûne, de chirurgie, de maladie aiguë","**Déshydratation**, hypotension, insuffisance rénale aiguë fonctionnelle","Gangrène de Fournier (infection grave du périnée, exceptionnelle)"],"it":[],"v":[],"sc":["Hydratation, tension, diurèse","**Signes d'infection génitale ou urinaire**","Nausées, vomissements, douleurs abdominales, polypnée (acidocétose)"],"sb":["Créatinine au début ; **cétonémie** en cas de symptômes (la glycémie peut être normale) ; la **glycosurie est normale** sous traitement"],"p":[],"edu":[],"cat":[],"r":["Font **uriner le glucose** ; protègent cœur et rein (insuffisance cardiaque, maladie rénale)","**Infections génitales**, déshydratation","**Acidocétose euglycémique** : cétonémie même si glycémie normale","**Suspendre 3 jours avant une chirurgie** et lors d'une maladie aiguë"],"err":[],"q":[],"f":["ado","m:metformine","m:diur-anse"],"_l":1},
{"n":"Traitement de l'hypoglycémie : glucose et glucagon","i":"hypoglycemie-ttt","s":"diab","nn":["Glucagon","Glucose hypertonique","Resucrage","Glucosé 30 %"],"d":["L'**hypoglycémie** (glycémie < 0,70 g/L chez le diabétique traité) est une **urgence** : le cerveau manque de glucose. Elle survient sous **insuline** ou **sulfamides/glinides**, en cas de repas sauté, d'effort ou d'alcool."],"ma":["Le **glucose** remonte directement la glycémie. Le **glucagon** libère le glucose stocké dans le foie (glycogène) : il est inefficace si les réserves sont épuisées (jeûne prolongé, alcoolisme, dénutrition)."],"sch":null,"m":[{"dci":"Sucre oral","br":"3 morceaux de sucre, 1 verre de jus de fruits ou de soda non light, gel de glucose","pr":"**15 g de sucres rapides**"},{"dci":"Glucosé 30 %","br":"ampoules de 10 ou 20 mL","pr":"IV directe (voie de bon calibre) puis relais par G10 %"},{"dci":"Glucagon","br":"GlucaGen® (IM, SC), Baqsimi® (nasal)","pr":"patient inconscient sans voie veineuse"}],"ind":["**Hypoglycémie** chez le diabétique traité, ou chez le non-diabétique (alcool, insuffisance surrénale, sepsis, nutrition)","Hypoglycémie sévère avec troubles de conscience, convulsions"],"ci":["Patient inconscient : **jamais de sucre par la bouche** (fausse route)","Glucagon : phéochromocytome, réserves en glycogène épuisées (inefficace)"],"ef":["Glucagon : nausées, vomissements","Glucosé 30 % : veinite (hypertonique)"],"eg":["Extravasation du glucosé hypertonique : nécrose cutanée","Hyperglycémie de rebond si resucrage excessif"],"it":[],"v":[],"sc":["**Glycémie capillaire** avant et après le resucrage, puis rapprochée","Conscience, comportement, sueurs, tremblements, pâleur, tachycardie","Recherche de la cause (repas, dose, effort, alcool, insuffisance rénale)"],"sb":["Glycémie veineuse de contrôle si doute ; bilan selon le contexte"],"p":[],"edu":[],"cat":[],"r":["Hypoglycémie < 0,70 g/L : **15 g de sucre**, **contrôle à 15 minutes**, puis collation","Inconscient : **rien par la bouche** ; G30 % IV ou glucagon 1 mg IM","Glucagon inefficace si réserves épuisées ; surveillance prolongée sous sulfamide"],"err":[],"q":[],"f":["s:hypoglycemie","m:insulines","m:sulfamides-hypo"],"_l":1},
{"n":"Hormones thyroïdiennes (lévothyroxine)","i":"levothyroxine","s":"endo","nn":["Hormones thyroïdiennes","Lévothyroxine","Levothyrox"],"d":["La **lévothyroxine** (T4) remplace l'hormone thyroïdienne manquante dans l'**hypothyroïdie** et après une **thyroïdectomie**. C'est un traitement à vie, très efficace, à **marge thérapeutique étroite** : de petites variations de dose ou d'absorption modifient l'équilibre."],"ma":["Identique à l'hormone naturelle, elle est transformée en **T3** active dans les tissus et rétablit le métabolisme (chaleur, énergie, fréquence cardiaque, transit). Par rétrocontrôle, elle fait baisser la **TSH**."],"sch":{"k":"hypophyse","cap":"La TSH, commandée par l'hypophyse, reflète l'équilibre du traitement."},"m":[{"dci":"Lévothyroxine","br":"Levothyrox®, L-Thyroxin Henning®, Euthyrox®, Thyrofix®","pr":"comprimés dosés de 25 à 200 µg ; gouttes buvables"},{"dci":"Liothyronine (T3)","br":"Cynomel®","pr":"indications particulières"}],"ind":["**Hypothyroïdie** (thyroïdite de Hashimoto, après iode radioactif, congénitale)","Après **thyroïdectomie** totale ; freination après un cancer thyroïdien"],"ci":["Hyperthyroïdie non traitée","Insuffisance surrénale non corrigée (corriger d'abord)","Prudence : maladie coronaire, troubles du rythme, personne âgée (débuter très bas)"],"ef":["Rares si la dose est adaptée"],"eg":["**Surdosage** = signes d'**hyperthyroïdie** : palpitations, tachycardie, fibrillation atriale, angor, insomnie, nervosité, tremblements, amaigrissement, diarrhée","Ostéoporose en cas de surdosage prolongé"],"it":["**Calcium, fer, antiacides, pansements gastriques, IPP, résines** : diminuent l'absorption (espacer d'au moins **2 à 4 heures**)","Inducteurs enzymatiques (rifampicine, carbamazépine) : besoins augmentés","AVK : effet renforcé en cas d'augmentation de dose"],"v":["Voie orale, **le matin à jeun**, **20 à 30 minutes avant le petit-déjeuner**, avec de l'eau, **tous les jours**","Ne pas changer de marque sans en parler (petites différences d'équilibre possibles)","Augmentation progressive des doses chez la personne âgée et le cardiaque"],"sc":["Signes d'hypo- ou d'hyperthyroïdie (fatigue, frilosité, palpitations, insomnie)","Pouls, poids, transit"],"sb":["**TSH** 6 à 8 semaines après chaque changement de dose, puis 1 à 2 fois par an une fois l'équilibre trouvé"],"p":["Personne âgée et coronarien : débuter à 12,5 ou 25 µg, augmenter lentement (risque d'angor)","Enfant : hypothyroïdie congénitale (dépistage à J3), traitement urgent pour le développement cérébral ; gouttes","Grossesse : **besoins augmentés** (souvent de 25 à 50 %), TSH dès le début de la grossesse puis régulièrement","Insuffisance cardiaque : prudence"],"edu":["Prendre chaque matin à jeun, **à distance du calcium, du fer, du café** et des antiacides","Traitement à vie ; ne pas arrêter ; contrôles de TSH réguliers","Signaler palpitations, insomnie, amaigrissement (surdosage) ou fatigue, frilosité (sous-dosage) ; prévenir en cas de grossesse"],"cat":["Palpitations, douleur thoracique : prévenir, ECG, TSH","TSH déséquilibrée : vérifier l'horaire de prise, les interactions et l'observance avant d'augmenter la dose"],"r":["Remplace la T4 ; **TSH 6 à 8 semaines** après chaque modification","**Le matin à jeun, 20 à 30 min avant le petit-déjeuner**, à distance du calcium et du fer","Surdosage = hyperthyroïdie ; débuter bas chez la personne âgée et le coronarien","Besoins augmentés pendant la grossesse"],"err":[],"q":[{"q":"Quand prendre la lévothyroxine ?","o":["Au coucher avec un yaourt","Le matin à jeun, 20 à 30 minutes avant le petit-déjeuner","Au milieu du repas de midi"],"a":1,"e":"L'absorption est meilleure à jeun et à distance des aliments, du calcium et du fer."},{"q":"Quel examen surveille l'équilibre d'un traitement par lévothyroxine ?","o":["La glycémie","La TSH","La calcémie"],"a":1,"e":"La TSH reflète l'action des hormones thyroïdiennes par rétrocontrôle sur l'hypophyse."}],"f":["m:antithyroidiens"]},
{"n":"Antithyroïdiens de synthèse et iode radioactif","i":"antithyroidiens","s":"endo","nn":["Antithyroïdiens de synthèse","Iode radioactif","Thiamazole","Carbimazole","Propylthiouracile"],"d":["Les **antithyroïdiens de synthèse** traitent l'**hyperthyroïdie** (maladie de Basedow, nodules toxiques) en bloquant la fabrication des hormones. L'**iode radioactif** (iode 131) et la chirurgie sont des traitements définitifs."],"ma":["Ils bloquent la **thyroperoxydase**, enzyme qui incorpore l'iode dans les hormones thyroïdiennes. L'**iode 131**, capté par la thyroïde, la détruit progressivement par irradiation."],"sch":{"k":"hypophyse","cap":"L'hyperthyroïdie freine la TSH ; les antithyroïdiens réduisent la production de T3 et T4."},"m":[{"dci":"Thiamazole","br":"Thyrozol®","pr":"référence"},{"dci":"Carbimazole","br":"Néo-Mercazole®","pr":"transformé en thiamazole"},{"dci":"Propylthiouracile","br":"Propylthiouracile®","pr":"1er trimestre de grossesse, crise aiguë"},{"dci":"Iode 131","br":"gélule ou solution","pr":"traitement définitif en médecine nucléaire"},{"dci":"Propranolol","br":"Avlocardyl®","pr":"traitement des symptômes (palpitations, tremblements)"}],"ind":["**Hyperthyroïdie** : maladie de Basedow (12 à 18 mois de traitement), préparation à la chirurgie ou à l'iode","Iode radioactif : Basedow récidivant, nodules toxiques, goitre"],"ci":["**Antécédent d'agranulocytose** ou d'hépatite sous antithyroïdien","Thiamazole et carbimazole : **1er trimestre de grossesse** (malformations : préférer le propylthiouracile)","Iode 131 : **grossesse et allaitement** (grossesse à éviter dans les 6 mois qui suivent)"],"ef":["Éruption cutanée, prurit","Douleurs articulaires, troubles digestifs, troubles du goût"],"eg":["**Agranulocytose** (chute brutale des polynucléaires) : fièvre, angine, ulcérations buccales","**Hépatite** (surtout propylthiouracile), vascularite","Hypothyroïdie (surdosage, après iode 131)"],"it":[],"v":[],"sc":["**Température**, mal de gorge, ulcérations buccales","Signes d'hyper- ou d'hypothyroïdie : pouls, poids, tremblements, sommeil","Peau (éruption), ictère"],"sb":["**NFS** avant le traitement puis **régulièrement les premiers mois** (souvent tous les 10 jours pendant 2 mois) et **en urgence si fièvre** ; **TSH, T4 libre** ; bilan hépatique"],"p":[],"edu":[],"cat":[],"r":["Bloquent la synthèse des hormones thyroïdiennes ; Basedow 12 à 18 mois","**Agranulocytose** : fièvre ou angine = **NFS en urgence**","Propylthiouracile au 1er trimestre de grossesse ; iode 131 contre-indiqué pendant la grossesse"],"err":[],"q":[],"f":["m:levothyroxine","m:bb"],"_l":1},
{"n":"Corticoïdes systémiques","i":"corticoides","s":"endo","nn":["Corticoïdes systémiques","Corticoïdes","Corticoïdes injectables","Corticoïdes pédiatriques","Hormones surrénaliennes","Minéralocorticoïdes","Hydrocortisone","Prednisone"],"d":["Les **corticoïdes** (glucocorticoïdes) sont de puissants **anti-inflammatoires** et **immunosuppresseurs**, utilisés dans de très nombreuses maladies : asthme, BPCO, maladies inflammatoires et auto-immunes, allergies, cancers, greffes, œdème cérébral. L'**hydrocortisone** sert aussi de traitement **substitutif** de l'insuffisance surrénale."],"ma":["Ils imitent le **cortisol** : ils pénètrent dans les cellules et modifient l'expression des gènes de l'inflammation (moins de prostaglandines, de leucotriènes, de cytokines) et de l'immunité. Ils agissent aussi sur le métabolisme (glycémie, protéines, os, sel et eau)."],"sch":{"k":"ains","cap":"Les corticoïdes agissent en amont des AINS, sur la libération de l'acide arachidonique."},"m":[{"dci":"Prednisone, prednisolone","br":"Cortancyl®, Solupred®","pr":"voie orale, référence"},{"dci":"Méthylprednisolone","br":"Médrol® (oral), Solumédrol® (IV)","pr":"bolus IV (poussées)"},{"dci":"Dexaméthasone","br":"Dectancyl®, injectable","pr":"œdème cérébral, chimiothérapie, Covid sévère"},{"dci":"Bétaméthasone","br":"Célestène®","pr":"maturation pulmonaire fœtale, formes buvables pour l'enfant"},{"dci":"Hydrocortisone","br":"Hydrocortisone Roussel®, injectable","pr":"insuffisance surrénale, choc septique"},{"dci":"Fludrocortisone","br":"Flucortac®","pr":"minéralocorticoïde (insuffisance surrénale)"}],"ind":["**Maladies inflammatoires et auto-immunes** (polyarthrite, lupus, vascularites, MICI, pseudo-polyarthrite rhizomélique)","**Exacerbations d'asthme et de BPCO**, laryngite de l'enfant, allergies sévères, œdème de Quincke (après l'adrénaline)","**Œdème cérébral**, prévention des vomissements de la chimiothérapie, hématologie","**Insuffisance surrénale** (hydrocortisone substitutive), choc septique réfractaire"],"ci":["**Infection non contrôlée** (bactérienne, virale : varicelle, zona, herpès oculaire ; parasitaire : anguillulose ; tuberculose)","**Vaccins vivants** sous corticothérapie à forte dose","Prudence : ulcère évolutif, diabète déséquilibré, HTA sévère, troubles psychiatriques, glaucome"],"ef":["**Hyperglycémie**, appétit augmenté, **prise de poids**, visage arrondi","**Insomnie**, excitation, troubles de l'humeur","**Rétention d'eau et de sel**, HTA, **hypokaliémie**","Fragilité cutanée, ecchymoses, retard de cicatrisation"],"eg":["**Infections** (parfois masquées : fièvre et douleur atténuées)","**Ostéoporose**, fractures ; fonte musculaire","**Insuffisance surrénale aiguë** à l'arrêt brutal d'un traitement prolongé","Diabète cortico-induit, décompensation psychiatrique, cataracte, glaucome, ulcère (surtout avec les AINS)"],"it":[],"v":[],"sc":["**Glycémie capillaire** (surtout chez le diabétique), **pression artérielle**, **poids**, œdèmes","Signes d'infection (même discrets), cicatrisation","Sommeil, humeur, comportement"],"sb":["**Glycémie, kaliémie**, bilan lipidique ; ostéodensitométrie si traitement prolongé ; dépistage de l'anguillulose chez les patients ayant séjourné en zone tropicale"],"p":[],"edu":[],"cat":[],"r":["Anti-inflammatoires et immunosuppresseurs puissants ; **prise le matin**","Effets : glycémie, poids, sel et eau, potassium, os, peau, infections, humeur","**Décroissance progressive** (insuffisance surrénale) ; jamais d'arrêt brutal","Pas de vaccin vivant à forte dose ; attention aux AINS (ulcère)"],"err":[],"q":[],"f":["corticoides","ains","m:ains","m:osteoporose"],"_l":1},
{"n":"Traitements de l'ostéoporose","i":"osteoporose","s":"endo","nn":["Traitements de l'ostéoporose","Bisphosphonates","Dénosumab","Modulateurs sélectifs des récepteurs aux œstrogènes (SERM)","Calcitonine","Anabolisants osseux","Biphosphonates en oncologie","Dénosumab en oncologie","Alendronate"],"d":["L'**ostéoporose** fragilise les os et expose aux **fractures** (poignet, vertèbres, col du fémur), surtout chez la femme ménopausée et la personne âgée, ou sous corticoïdes. Les traitements diminuent le risque de fracture ; ils s'associent à la **prévention des chutes** et aux apports en **calcium et vitamine D**."],"ma":["Les **bisphosphonates** et le **dénosumab** freinent les **ostéoclastes** qui détruisent l'os. Le **tériparatide** et le **romosozumab** stimulent les **ostéoblastes** qui le fabriquent (anabolisants). Les **SERM** (raloxifène) imitent l'effet protecteur des œstrogènes sur l'os."],"sch":{"k":"os","cap":"Dans l'ostéoporose, l'os spongieux perd sa densité : les traitements freinent sa destruction ou stimulent sa fabrication."},"m":[{"dci":"Alendronate, risédronate","br":"Fosamax®, Actonel®","pr":"bisphosphonates oraux hebdomadaires"},{"dci":"Acide zolédronique","br":"Aclasta®","pr":"bisphosphonate IV annuel (Zometa® en oncologie)"},{"dci":"Dénosumab","br":"Prolia® (Xgeva® en oncologie)","pr":"SC tous les 6 mois"},{"dci":"Tériparatide","br":"Forsteo® et génériques","pr":"SC quotidienne pendant 18 à 24 mois"},{"dci":"Romosozumab","br":"Evenity®","pr":"SC mensuelle, 12 mois"},{"dci":"Raloxifène","br":"Evista®","pr":"SERM"},{"dci":"Calcium + vitamine D","br":"Cacit D3®, Orocal D3® ; cholécalciférol","pr":"apports de base"}],"ind":["**Ostéoporose** post-ménopausique, masculine, **cortisonique** (traitement prolongé)","Après une **fracture par fragilité** (prévention de la suivante)","Oncologie : métastases osseuses, hypercalcémie maligne (zolédronate, dénosumab)"],"ci":["Bisphosphonates oraux : **impossibilité de rester assis ou debout 30 minutes**, troubles de l'œsophage, **hypocalcémie**, insuffisance rénale sévère","Dénosumab : hypocalcémie non corrigée","Tériparatide : maladie de Paget, antécédent de radiothérapie osseuse ; romosozumab : antécédent d'infarctus ou d'AVC"],"ef":["Bisphosphonates oraux : brûlures œsophagiennes, douleurs abdominales","Zolédronate IV : **syndrome pseudo-grippal** (fièvre, courbatures) dans les jours suivant la perfusion","Douleurs musculaires et osseuses"],"eg":["**Ostéonécrose de la mâchoire** (surtout à fortes doses en oncologie, après soins dentaires invasifs)","**Fractures atypiques du fémur** (traitement très prolongé)","**Hypocalcémie** (dénosumab, zolédronate)","Dénosumab : **fractures vertébrales multiples à l'arrêt** si non relayé"],"it":[],"v":[],"sc":["Douleurs œsophagiennes, déglutition","**État bucco-dentaire** (bilan dentaire avant le traitement)","Douleur de la cuisse ou de l'aine (fracture atypique)"],"sb":["**Calcémie**, vitamine D (25-OH), créatinine avant le traitement ; ostéodensitométrie de suivi"],"p":[],"edu":[],"cat":[],"r":["Bisphosphonates oraux : **à jeun, eau plate, 30 minutes assis ou debout**","**Ostéonécrose de la mâchoire** : bilan dentaire avant","**Dénosumab** tous les 6 mois, **jamais d'arrêt sans relais**","Calcium, vitamine D et prévention des chutes"],"err":[],"q":[],"f":["m:calcium-mg","m:corticoides"],"_l":1}
]);
